import type { SearchHit } from '../../../../../packages/contracts/src/search.js';

export function calculateRecall(approximate: readonly SearchHit[], exact: readonly SearchHit[]): number | null {
  if (exact.length === 0) return null;
  const approximateIds = new Set(approximate.map((hit) => hit.id));
  return exact.filter((hit) => approximateIds.has(hit.id)).length / exact.length;
}
