import { React, createContext, useContext, useSyncExternalStore, useRef } from '../shared/react.js';
import { AppRuntime } from './app.runtime.js';
import type { AppState } from './app.types.js';

const RuntimeContext = createContext(null as AppRuntime | null);

export function AppRuntimeProvider(props: { readonly runtime: AppRuntime; readonly children?: unknown }) {
  return <RuntimeContext.Provider value={props.runtime}>{props.children}</RuntimeContext.Provider>;
}

export function useAppRuntime(): AppRuntime {
  const runtime = useContext(RuntimeContext) as AppRuntime | null;
  if (!runtime) throw new Error('AppRuntimeProvider is missing.');
  return runtime;
}

export function useAppState(): AppState {
  const runtime = useAppRuntime();
  return useSyncExternalStore(runtime.store.subscribe, runtime.store.getSnapshot, runtime.store.getSnapshot) as AppState;
}

export function useAppSelector<T>(select: (state: AppState) => T): T {
  const runtime = useAppRuntime();
  const previous = useRef(null as { state: AppState; value: T } | null);
  const snapshot = () => {
    const state = runtime.store.getSnapshot();
    if (previous.current?.state === state) return previous.current.value;
    const value = select(state);
    if (!previous.current || !Object.is(previous.current.value, value)) previous.current = { state, value };
    return previous.current.value;
  };
  return useSyncExternalStore(runtime.store.subscribe, snapshot, snapshot) as T;
}

export function useGalleryState(): AppState {
  const previous = useRef(null as AppState | null);
  return useAppSelector(state => {
    const last = previous.current;
    const ignored = new Set(['draftQuery', 'corpusImageProgress', 'indexBuildProgress', 'visualIndexProgress', 'feedbackMessage']);
    if (last && (Object.keys(state) as (keyof AppState)[]).every(key => ignored.has(key) || Object.is(last[key], state[key]))) return last;
    previous.current = state;
    return state;
  });
}
