import { React, useState } from '../react.js';
import { canResize, imagePriority, imageSrcSet, imageUrl, mediumSource, type ImageRole } from '../images/image-sizing.js';
const decodedSources = new Map<string, string>();

interface ArtworkImageProps {
  readonly src: string | null | undefined;
  readonly alt: string;
  readonly className?: string;
  readonly eager?: boolean;
  readonly priority?: boolean;
  readonly role?: ImageRole;
  readonly sizes?: string;
  readonly fallbackSrc?: string | null;
  readonly fallbackLabel?: string;
  readonly draggable?: boolean;
  readonly width?: number | null;
  readonly height?: number | null;
  readonly dominantColor?: string;
}

export function ArtworkImage(props: ArtworkImageProps) {
  return <ImageResource key={props.src ?? 'missing'} {...props}/>;
}

function ImageResource(props: ArtworkImageProps) {
  const [attempt, setAttempt] = useState(0);
  const [ready, setReady] = useState(false);
  const source = attempt === 3 ? props.fallbackSrc : props.src;
  const role = props.role ?? 'tile';
  const format = attempt === 0 ? 'avif' : attempt === 1 ? 'webp' : 'jpeg';
  const preview = decodedSources.get(mediumSource(props.fallbackSrc ?? source ?? ''));
  const style = { backgroundColor: props.dominantColor ?? '#efeee8', aspectRatio: `${props.width || 1} / ${props.height || 1}`,
    backgroundImage: role === 'detail' && !ready && preview ? `url("${preview}")` : undefined, backgroundSize: 'cover', backgroundPosition: 'center' };
  const exhaustedFallback = attempt === 3 && mediumSource(props.fallbackSrc ?? '') === mediumSource(props.src ?? '');
  if (!source || attempt > 3 || exhaustedFallback) {
    return <span className={`artwork-image-fallback ${props.className ?? ''}`} role="img"
      aria-label={props.alt || props.fallbackLabel || 'Artwork image unavailable'} style={style}>
      <span aria-hidden="true">N</span><small>{props.fallbackLabel ?? 'Image unavailable'}</small>
    </span>;
  }
  return <img
    className={`${props.className ?? ''}${ready ? ' is-ready' : ' is-loading'}`.trim()}
    src={imageUrl(source, role === 'detail' ? 640 : 160, format)}
    srcSet={imageSrcSet(source, role, format)}
    sizes={props.sizes ?? (role === 'detail' ? '(max-width: 640px) 90vw, 300px' : '80px')}
    alt={props.alt} width={props.width || 1} height={props.height || 1}
    {...imagePriority(props.eager, props.priority)}
    draggable={props.draggable ?? false} style={style}
    onLoad={(event: any) => {
      setReady(true);
      const key = mediumSource(source);
      decodedSources.delete(key); decodedSources.set(key, event.currentTarget.currentSrc);
      if (decodedSources.size > 96) decodedSources.delete(decodedSources.keys().next().value!);
    }} onError={() => { setReady(false); setAttempt(canResize(source) && attempt < 2 ? attempt + 1 : attempt === 3 ? 4 : 3); }}
  />;
}
